import{_ as a}from"./chunks/bcd04697032471548049.BwLQcnEo.js";import{_ as r,C as o,o as i,c as l,j as e,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"想法是新时代的石油（在数字时代，越来越多人如何致富）","description":"","frontmatter":{"title":"想法是新时代的石油（在数字时代，越来越多人如何致富）","originalTitle":"Ideas Are The New Oil (How More People Get Rich In The Digital Era)","date":"2024-06-01","originalUrl":"https://thedankoe.com/letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era/","minutes":14,"sourceHash":"68f147f42e8a6fd7b4862d1e13c758d06f4ac700a2c79ff9c51c1713f37a9911","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era/"}]]},"headers":[],"relativePath":"letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era.md","filePath":"letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era.md"}'),c={name:"letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era.md"};function m(d,p,g,f,u,_){const t=o("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"想法是新时代的石油-在数字时代-越来越多人如何致富",tabindex:"-1"},[n("想法是新时代的石油（在数字时代，越来越多人如何致富） "),e("a",{class:"header-anchor",href:"#想法是新时代的石油-在数字时代-越来越多人如何致富","aria-label":'Permalink to "想法是新时代的石油（在数字时代，越来越多人如何致富）"'},"​")],-1)),s(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/fJKeB3fz4_Q?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在这封信中，我想探讨：</p><ul><li>为什么投资对大多数人来说是个愚蠢的决定。</li><li>为什么房地产不能让你致富。</li><li>为什么想法是任何人都可以开采的新石油。</li><li>为什么在20年后，数字房地产将被视为这一代人创造财富的方法。</li><li>为什么创作者经济是新经济，并且如果你想创造新财富，这很可能是你要走的路径。</li><li>究竟该建立什么样的数字房地产、如何建立，以及按什么顺序建立。</li></ul><p>我从很小的时候就致力于创业。</p><p>很容易看出商业是一场无限游戏。只要我一直玩下去就不会输的游戏。这种游戏不会把我困在企业阶梯中无聊的职位上，让我注定只能拿到固定数额的钱，从而过上固定质量的生活。</p><p>很容易看出，商业是掌控我的未来、我的收入，以及我每天在任何给定时刻做什么的唯一途径。</p><p>像其他人一样，我一开始也完全不知道自己在干什么。</p><p>我以为致富只有两条路。</p><p><strong>第一条路是投资。</strong></p><p>我妈妈总是坚决要求我早点开始。她鼓励我东投一点西投几块，因为40年后它可能会变成几百万。</p><p>我很高兴这对我来说从来都说不通，因为直到现在它依然说不通。</p><p>当我可以借助互联网以接近零成本创办自己的企业，并作为一人企业在2-4年内赚取几百万利润时，我为什么要活在稀缺心态中，把我辛苦赚来的最后一点钱拿去投资，就为了在我生命快结束时赚那<em>区区几百万</em>？然后，一旦我有了充裕的钱去投资，我就能把这笔钱在股市或加密货币中变成超过1000万美元。</p><p><strong>第二种选择是房地产。</strong></p><p>我一直看到一些疯传的视频，讲的是一个年轻人问婴儿潮一代（boomers）他们是如何致富的。</p><p>人们一直在发布这些视频的合集，声称“他们说的都一样”，就好像在暗示这是任何人致富的绝佳途径。</p><p>视频中大多数婴儿潮一代都说他们是靠房地产致富的。</p><p>我不否认，对于<em>有</em>钱人来说，房地产是一个不错的选择，但对于那些仍然被困在父母“投资最后一分钱”的思想中、同时被迫呆在无聊的工作岗位上为他们不切实际的致富美梦提供资金的新手来说……那是不可能发生的。至少在你有生之年的任何有意义的时间尺度内是不可能的。</p><p>我的观点是：</p><p>大多数人不知道该做什么来创造新财富。</p><p>我想说你其实是知道的。你现在就在看着它。但你仍然抱有“消费和储蓄”的心态，这限制了你如何看待正发生在你眼前的淘金热。</p><p>所有的巨额新财富都在数字空间中被创造出来。</p><p><strong>在我们开始之前：</strong></p><p>《心智变现》（Mental Monetization）将在2天后（周一）发布。</p><p>届时价格将从150美元上涨至225美元。</p><p>如果你想用一种能在你睡觉时依然产生销售的数字产品将你的创意工作变现（而不是做自由职业或客户工作）——即使你几乎没有粉丝——<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">点击此处注册，上线后你就能获得访问权限。</a></p><h2 id="想法是新时代的石油——玩无限数字游戏" tabindex="-1">想法是新时代的石油——玩无限数字游戏 <a class="header-anchor" href="#想法是新时代的石油——玩无限数字游戏" aria-label="Permalink to &quot;想法是新时代的石油——玩无限数字游戏&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>我们正处于历史上的一个关键时刻。</p><p>人工智能的冲击正威胁着专家的生计。在动物界，灭绝的主要原因是过度特化，就像一种长嘴鸟，繁衍到最后自己飞不起来，它的后代也无法觅食。</p><p>在一个计算机作为超级专家的世界里，过度专业化的人也是如此。</p><p>人们害怕自己会被取代。</p><p>无论如何，人们在工作中得不到满足感，这种感觉渗透到他们生活的其他领域，导致他们缺乏动力去做出任何改变。</p><p>当石油和房地产的实体路线正在枯竭（而且首先就需要大量资源才能进入）时，年轻人不知道该走哪条路来创造财富。</p><p>简而言之，人们脑子里想的唯一一件事就是生存资源。</p><p>在今天的世界里，这就意味着金钱和财富的创造。</p><p>理解接下来这句话，因为它不是什么新鲜事：</p><p>让上一代人致富的东西不会让你致富。</p><p>所有的新财富都在数字空间中产生。</p><p>想法空间。</p><p>新贵们不再开采有限的物理资源。他们在合成被称为“想法”的无限资源。</p><p>物理世界有其极限。它成本高昂，盖房子、运送产品和传播信息都需要花费大量时间。</p><p>为什么好想法如此重要？</p><p>因为执行力比以往任何时候都更容易获得。</p><p>我们不再生活在一个执行比想法更重要的世界里。我们生活在一个想法的质量、想法的传播和想法的迭代能带来富裕生活的世界里。</p><p>数字世界没有极限，特别是当我们不断将专业任务外包给人工智能时。</p><p>通过在互联网上专注学习，你可以在任何技能或兴趣领域成为前10%的人。</p><p>你可以作为创作者建立一家一人企业（我们经常忘记这在几年前还是不可能的，现在几乎任何人都能做到。如果他们做不到，那就是技能问题）。</p><p>“但是 Dan，不是每个人都能成为创作者的！”</p><p>如果你把格局打开去思考，是的，他们可以。我把我的逻辑留到另一封信里再讲。</p><p>想法工作者在数字时代茁壮成长。</p><p>数字房地产可以零成本建立。</p><p>数字产品可以以极低的边际成本建立和分发。</p><p>数字通讯可以触达任何连接互联网的人。</p><p>数字社会，有时也被称为创作者经济，正是创造新财富的地方。</p><h2 id="如何驾驭这场数字淘金热" tabindex="-1">如何驾驭这场数字淘金热 <a class="header-anchor" href="#如何驾驭这场数字淘金热" aria-label="Permalink to &quot;如何驾驭这场数字淘金热&quot;">​</a></h2><p>身边流传着一个常见的建议，我认为它非常狭隘且愚蠢：</p><p><em>“先在线下做点什么，然后再开始线上。”</em></p><p>换句话说，人们没有意识到社交媒体（或互联网）在当今世界是<em>创办</em>企业一种完全可行的方式。我敢说，综合考虑，这是最好的方式之一。</p><p>我不认为不必要地去承受建立实体店或实体服务（如害虫防治、汽车美容等），甚至做那种需要无休止人工拓客的自由职业或代理机构工作的痛苦和折磨是明智的。</p><p>即便如此，那些企业只要他们 f*cking 想获客，随时都可以上社交媒体。他们不需要等到满足了你的成功标准，才开始在这个新的城市广场上发帖。</p><p>把社交媒体当作一种能吸引任何人、连接任何人并为你任何工作成果建立分发渠道的方式，却对它视而不见，这根本说不通。</p><p>当然，我建议你自己独立思考，追求自己的兴趣，并用合适的技能组合将其转化为一门生意。</p><p>我不建议接受别人过时的商业意识形态，那会局限你的思维，让你看不到自己的潜力。</p><p>换句话说，我建议你选择你想要解决的问题和你想提供的解决方案。我甚至建议你不要去“创业”。我建议把你学到的任何技能、解决的任何问题、创造的任何解决方案都视为可以提供给他人的价值，作为你一生的事业。</p><p>除了解决你生活中的问题、获得解决问题的技能，并将这些经验作为内容和产品传承下去，以此靠做自己喜欢的事情谋生之外，没有必要做任何其他事情。</p><h3 id="数字社会" tabindex="-1">数字社会 <a class="header-anchor" href="#数字社会" aria-label="Permalink to &quot;数字社会&quot;">​</a></h3><p>无论你对未来有何信念，都很难反驳创作内容的价值。</p><p>创作者是大公司声誉的前沿阵地（创始人和高管都有个人品牌，比如埃隆）。</p><p>创作者能最先挑选好工作（因为他们在内容中证明了自己的价值）。</p><p>创作者为其他创作者工作，以获取经验和杠杆。</p><p>创作者是公司作为赞助商寻找的第一批人，以此将他们的产品推广到各个细分市场。</p><p>创作者是消费者为了人际连接（而不是梗图或公司动态）而主动关注的唯一账号。</p><p>做一名创作者不是什么花里胡哨的互联网工作。它是一种新的生活方式，而且我只看到它变得越来越重要。</p><p>事实上，我强烈建议不要成为一名“创作者”。</p><p>我只建议吸引一个社区、提升你自己、获得新技能，并分发价值。</p><p>你知道的……这些在物理世界中已经算是通向美好生活秘诀的东西，在数字世界中被无限放大了。</p><p>创作者的一人企业只是一种让你的努力方向更清晰的意识形态方式。</p><h3 id="成为唯一的细分领域-niche-of-one-——你的个人垄断" tabindex="-1">成为唯一的细分领域（Niche Of One）——你的个人垄断 <a class="header-anchor" href="#成为唯一的细分领域-niche-of-one-——你的个人垄断" aria-label="Permalink to &quot;成为唯一的细分领域（Niche Of One）——你的个人垄断&quot;">​</a></h3><blockquote><p>传统教育和极度专业化是让人屈从于主导范式/系统的一种方式。研究自然界的普遍原则，成为一名深度通才。——丹尼尔·施马赫滕贝格（Daniel Schmachtenberger）</p></blockquote><p>我们在<a href="/letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests">《通才时代》</a>中讨论过这个问题，但向下深耕细分领域是一条增加竞争、沦为客户（或雇主）奴隶、并在技术进一步发展时无法适应的绝佳途径。</p><p>仅仅因为它在十年前有用，并不意味着“缩小细分领域”的教导就应该坚持下去。商业是相似的，但也截然不同。我完全可以在舒适的家里输入某个人的网址，而不是开车去他们的实体店。</p><p>让我们把这弄简单点。</p><ol><li>思考你想在生活中实现什么。</li><li>写下你为达到目标而学到的兴趣和技能。</li><li>吸引其他在生活中试图实现同样目标的人。</li><li>利用你的兴趣和技能组合作为让你变得独一无二的方式。</li></ol><p>大多数人对生活的诉求是相同的。</p><p>他们想要更多的钱、更少的不安全感，更多的性、更少的孤独，更多的使命感、更少的混乱，等等。</p><p>我们都朝着同一个最终目标前进。</p><p>自我实现。</p><p>如果你是一个价值创作者（不是网红），那就是你的细分领域。</p><p>你根据自己的经验为了达到那个目标所谈论和建立的东西，才是让你独一无二的原因。</p><p>埃隆·马斯克正在制造火箭，将人类扩展到火星，这样我们就能作为一个物种实现自我。当你深入研究时，每一个<em>真正提供某种形式价值（因为真正的价值=转变和解决问题）</em>的企业或品牌，他们的细分领域都是自我实现。</p><p>你和我都可以追求更多的金钱和意义，但我会谈论写作和生产力，而你会谈论预算和灵性。</p><p>如果我们这辈子都写50,000条推文，只要所有这些帖子都符合自我实现这个宏大愿景，我们具体谈论什么其实并不重要。</p><p>你是一个体验的容器。</p><p>当你把这种体验传承给别人去利用时，你就成为了唯一的细分领域。</p><h3 id="你的数字房地产投资组合" tabindex="-1">你的数字房地产投资组合 <a class="header-anchor" href="#你的数字房地产投资组合" aria-label="Permalink to &quot;你的数字房地产投资组合&quot;">​</a></h3><p>你建立的数字地产能吸引多少人占据，决定了你能否在这场新的淘金热中取得成功。</p><p>这里有两类数字地产：</p><ol><li><strong>免费</strong> —— 通过内容、新闻通讯和免费产品来吸引并建立受众群体的方式。</li><li><strong>付费</strong> —— 你如何通过数字产品，将你建立的免费地产变现。</li></ol><p>让我们梳理一下你应该建立什么，为什么它很重要，以及你应该遵循的进展路线：</p><p><strong>1) 在一个社交媒体平台上发布日常内容</strong></p><p>在商业领域，我看到的最大问题总体上是人们把注意力集中在了错误的事情上。</p><p>当他们本该去寻找客户时，他们却在建网站。</p><p>当他们本该去吸引受众时，他们却在做产品。</p><p>当他们本该去做任何其他实际有用的事情时，他们却在注册有限责任公司（LLC）和设计Logo。</p><p>这种毫无优先级的做法简直在昭告天下：你根本不知道自己在干什么。</p><p>在商业中，你需要一个想付钱给你的人，以及一个收款的方式。</p><p>作为一个初学者，除非涉及到为免费客户实践并取得成果，否则你不应该关注任何其他事情（注意，我没说“建立作品集”，那几乎毫无用处。去免费帮助<em>人</em>。）</p><p>这个拼图的第一块就是“想付钱给你的人”。</p><p>也就是，受众。</p><p>为什么要受众？</p><p>因为我假设你和我一样，想要杠杆。</p><p>你不想通过接客户的活儿来给自己制造第二份朝九晚五的工作。</p><p>你想创造任何你想要的东西。</p><p>你想掌控你每一天的时间。</p><p>你想在睡觉时也能实现销售。</p><p>在当今世界，实现这一目标最容易上手的方式就是在社交媒体上建立受众。</p><p>为了做到这一点，在一个平台上每天写内容，直到你掌握了增长的窍门，这就是你目前的重点。</p><p>以下是你的第一批内容创意：</p><ul><li>讲述你的故事以及你所实现的转变。</li><li>拆解你的任何技能和兴趣（教人们怎么做）。</li><li>讨论人们在追求目标时面临的问题以及如何解决它们。</li><li>记录你在追求目标的过程中学到的经验教训。</li><li>分享你偶然发现并想将其内化的想法（来自书籍、对话或播客）。</li></ul><p>从那里开始。</p><p>或者，直接研究你想成为的那10个账号正在做什么，拿走他们最好的想法，然后变成你自己的。还记得你以前在学校里怎么“用自己的话总结”吗？这里也是一样的。</p><p>社交媒体是一门技能，而不是纯粹的运气。</p><p>当人们甚至没有花过一个小时去研究这门技能时，他们总是认为这靠的是运气或魔法。</p><p>我用来撰写内容和实现增长的确切系统就在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 里。</p><p><strong>2) 用新闻通讯将你的受众去平台化</strong></p><p>社交媒体平台仍然是中心化的。</p><p>平台公司拥有算法、你的数据，以及你发布的任何内容。</p><p>所以，要把你的粉丝引导到邮件列表中，因为你可以随时下载这个列表，你真正拥有它。</p><p>每周发送一封新闻通讯，深入拓展你在社交媒体上最好的帖子。</p><p>大多数社交媒体内容都是宽泛的、入门级的，并且旨在提供快速的娱乐。很少有人会直接在社交媒体上向你购买东西。</p><p>你的新闻通讯才是你免费提供更深层洞察的地方，并通过推广你的产品来将你的个人品牌变现。</p><p><strong>3) 打造一款免费产品来建立权威</strong></p><p>你可能在想，如果我不深耕细分领域，我要怎么做销售？</p><p>把你的社交媒体想象成你业务的第一层。</p><p>就像一个漏斗。</p><p>你围绕一个令人向往的目标吸引广泛的受众，然后通过一款免费产品建立权威，这款产品会针对某项特定技能或兴趣提供有价值的免费建议。从那里，你可以将他们引向围绕同一主题的付费产品。</p><p>所以：</p><p>宽泛的内容 &gt; 更具体的免费产品以建立权威 &gt; 付费数字产品 &gt; 创造更多免费产品以保持新鲜感并让销售源源不断。</p><p>这个免费产品是一个引流品（lead magnet）；下载它的人会被添加到你的邮件列表中。你的引流品还有其他几个作用：</p><ol><li><strong>创造客户</strong> —— 你的工作是教育你的受众，直到他们成为你其他产品的客户。</li><li><strong>写你所想</strong> —— 当你拥有一个引流品时，你关于某个主题的所有权威信息都集中在一个地方。你不必再担心在时间线上写太多相关内容。你只需经常推广这个引流品即可。</li><li><strong>销售产品</strong> —— 你的引流品应该给人们提供足够的信息，让他们产生购买你产品的信任。你应该在引流品的结尾推广你的产品，趁着“潜在客户”热情高涨时达成销售。</li></ol><p>当你创建多个免费下载物/引流品时，你会大幅提升你的权威性。</p><p>你在更深的层面上教育人们。</p><p>他们会更喜欢你。他们会与你进行更多的互动。他们会在私信里开启对话。他们觉得你比别人贡献了更多的价值。换句话说，你的互动率之所以很差，可能正是因为你从未带你的受众进入比社交媒体更深的层次。</p><p>马克·曼森（Mark Manson）和詹姆斯·克莱尔（James Clear）不需要担心去优化他们的内容，因为有那么多人已经购买并阅读了他们的书。人们花了好几个小时沉浸在他们的思想中。</p><p>接下来，你所要做的就是专注于写内容，为你的免费产品引流，并在推广你产品的同时创作有价值的新闻通讯。</p><p>你可以创建模板、清单、灵感素材库（swipe files）或诸如此类的东西，但我个人更喜欢通过迷你课程或电子书来创建能帮助受众实现<em>一个小巧而令人向往的目标</em>的免费产品。这正是我在我的 <a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">一人企业基础教程免费产品（One Person Business Foundations free product）</a> 中所做的事。</p><p><strong>4) 用数字产品组合来变现</strong></p><p>你已经建立了充足的数字地产。</p><p>从技术上讲，你可以将社交媒体变现、获取新闻通讯赞助，或者开启付费通讯，但这些都不是最优化或最赚钱的变现方式。</p><p>当人们这么做时，你就会听到“这个账号有几百万粉丝，但每月只能赚一万美元”之类的故事。</p><p>相反，去打造一款数字产品，这样你就能对自己的收入拥有完全的控制权。</p><p>我不赞同只做一两款数字产品就觉得大功告成了。</p><p>我主张通过不断发布、改进和迭代，直到你拥有能创造高基础收入的完美数字产品组合，从而让成功和收入变得几乎得到保证。</p><p>之后，你可以通过工作坊或活动等微型产品来变现——你只需为一两次通话收取较低的价格，每1-2个月发布一次——从而在基础收入之上看到可预测的收入飙升。</p><p>我在 <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a> 中教授了所有这些内容（提醒一下，早鸟价还有2天结束）。</p><p><strong>5) 多元化布局平台，专注受众</strong></p><p>到目前为止，你已经拥有了一个不断增长的受众群体、用来建立权威的免费产品、一份让你与受众保持紧密联系的每周新闻通讯，以及一组不断增加的数字产品，这些产品的利润随着受众的增长而增长（因为有更多的人看到并购买它们）。</p><p>最后一点至关重要。</p><p>当你已经在数字空间建立了自己的业务并且实现了盈利，现在你可以拿出所有最好的内容创意，把它们分发到其他平台上。</p><p>你可以通过告诉现有的受众去关注你并分享你的内容，来启动播客、YouTube或Instagram上的受众群体。</p><p>随着你的各个平台不断增长，人们下载你的免费产品、阅读你的新闻通讯，并购买你的付费产品；这时指数级增长就开始了。你可以在一年之内让收入翻倍、达到原来的三倍甚至四倍。</p><p>这就是我如何从仅靠大量的 X 粉丝年入 80 万美元，到去年通过多元化的受众群体赚到约 400 万美元的过程。</p><p>就是这样。</p><p>这就是全貌。</p><p>你现在有了方向，接下来就靠你自己通过经验和失败去学习技术细节了。</p><p>感谢阅读。</p><p>祝你周末愉快。</p><p>—— 丹 (Dan)</p><hr><p><a href="/en/letters/ideas-are-the-new-oil-how-more-people-get-rich-in-the-digital-era">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',170))])}const P=r(c,[["render",m]]);export{k as __pageData,P as default};
